// Repro: the ops shell and the radar feed should stack, not sit in a row.
await page.goto('/ops/radar');

const shell = page.getByRole('navigation', { name: 'Ops' });
const feed = page.getByRole('region', { name: 'Radar feed' });
await expect(shell).toBeVisible();
await expect(feed).toBeVisible();

const a = await shell.boundingBox();
const b = await feed.boundingBox();
// Stacked: one box lies fully below the other. Row layout: both share the same vertical band.
const stacked = b.y >= a.y + a.height - 1 || a.y >= b.y + b.height - 1;

// Report the measured layout through an element so the assertion is a supported expect.
await page.evaluate((ok) => {
  const d = document.createElement('div');
  d.id = 'layout-check';
  d.textContent = ok ? 'stacked' : 'side-by-side';
  document.body.appendChild(d);
}, stacked);

await expect(page.locator('#layout-check')).toHaveText('stacked');
```

